#include <bits/stdc++.h>
using namespace std;
int main(){
    int n, cs=0;
    while (cin >> n && n != 0) {
        vector<long long> a(n);
        for (auto &x : a) cin >> x;
        vector<long long> sums;
        for (int i=0;i<n;i++) for (int j=i+1;j<n;j++) sums.push_back(a[i]+a[j]);
        sort(sums.begin(), sums.end());
        int m; cin >> m;
        cout << "Case " << ++cs << ":\n";
        for (int k=0;k<m;k++){
            long long q; cin >> q;
            auto it = lower_bound(sums.begin(), sums.end(), q);
            long long best = 0, bestDiff = LLONG_MAX;
            if (it != sums.end()) { long long d = llabs(*it-q); if (d<bestDiff){bestDiff=d; best=*it;} }
            if (it != sums.begin()) { auto p = prev(it); long long d = llabs(*p-q); if (d<bestDiff || (d==bestDiff && *p<best)){bestDiff=d; best=*p;} }
            cout << "Closest sum to " << q << " is " << best << ".\n";
        }
    }
}

